#include <windows.h>
#include <cstdio>
#include "MVDCore.h"
#include "NPointCalibCpp.h"
using namespace VisionDesigner;using namespace VisionDesigner::NPointCalib;
int main(int argc,char**argv){SetErrorMode(SEM_FAILCRITICALERRORS|SEM_NOGPFAULTERRORBOX);if(argc!=3)return 2;setvbuf(stdout,nullptr,_IONBF,0);SetDllDirectoryA(argv[1]);auto lib=LoadLibraryA("MVDNPointCalibCpp.dll");if(!lib)return 3;auto create=(int(__stdcall*)(INPointCalibTool**))GetProcAddress(lib,"CreateNPointCalibToolInstance");auto destroy=(int(__stdcall*)(INPointCalibTool*))GetProcAddress(lib,"DestroyNPointCalibToolInstance");FILE*f=nullptr;fopen_s(&f,argv[2],"r");if(!f)return 4;int frame,count;while(fscanf_s(f,"%d%d",&frame,&count)==2){INPointCalibTool*tool=nullptr;if(create(&tool))return 5;try{auto basic=tool->GetBasicParam();basic->SetCameraMode((MVD_CAMERA_MODE)1);tool->SetRunParam("HomoFreedom","2");tool->SetRunParam("WeightFun","1");for(int i=0;i<count;i++){float x,y,u,v;fscanf_s(f,"%f%f%f%f",&x,&y,&u,&v);basic->AddOffsetPoint({x,y},{u,v});}tool->Run();auto r=tool->GetResult()->GetPlatformCalibInfo();float h[9];r->GetHomoMatrix(h);printf("{\"frame\":%d,\"count\":%d,\"status\":%d,\"matrix\":[",frame,count,r->GetStatus());for(int j=0;j<9;j++)printf("%s%.9g",j?",":"",h[j]);printf("]}\n");}catch(IMVDException&e){printf("{\"frame\":%d,\"code\":%u}\n",frame,e.GetErrorCode());}destroy(tool);}fclose(f);return 0;}
